from collections import deque

def parcours(graphe, depart):
    visites = {depart}
    a_explorer = deque([depart])
    while a_explorer:
        sommet = a_explorer.popleft()
        for voisin in graphe[sommet]:
            if voisin not in visites:
                visites.add(voisin)
                a_explorer.append(voisin)
    return visites

